import React from 'react';
import styled from 'styled-components';

import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { DOMProps } from '../../../../core/types/dom.js';
import { WithChildren } from '../../../../core/types/with-children.js';
import { Checkbox } from '../../../../forms/checkbox/Checkbox.js';

// #region StyledComponents
const VisibilityCheckboxWrapper = /* @__PURE__ */ styled.div({
  borderRadius: Spacings.Size8,
  '& label': {
    paddingRight: Spacings.Size8,
  },
});
// #endregion StyledComponents

export interface VisibilityCheckboxProps extends WithChildren, DOMProps {
  /**
   * Name of the checkbox.
   */
  name: string;

  /**
   * Visibility column accessor or id.
   */
  accessorOrId: string;

  /**
   * The usual checked property.
   */
  checked: boolean | 'indeterminate';

  /**
   * The usual change listener.
   *
   * @param accessorOrId - accessor or id of column
   * @param checked -
   */
  checkboxOnChange: (accessorOrId: string, checked: boolean) => void;

  /**
   * Flex order based on screen size.
   */
  order?: number;
}

/**
 * Checkbox for column visibility.
 *
 * @param props - name etc
 * @returns Flex wrapping Checkbox
 */
export function VisibilityCheckbox(
  props: VisibilityCheckboxProps,
): React.ReactElement {
  const { accessorOrId, checked, checkboxOnChange, name, order } = props;

  return (
    <VisibilityCheckboxWrapper
      key={accessorOrId}
      style={{
        order,
        paddingTop: Spacings.Size6,
        paddingBottom: Spacings.Size6,
      }}
    >
      <Checkbox
        key={accessorOrId}
        name={accessorOrId}
        value={checked}
        onChange={(value) => checkboxOnChange(accessorOrId, value)}
      >
        {name}
      </Checkbox>
    </VisibilityCheckboxWrapper>
  );
}
